-- Narrow opt-in bootstrap: fixed native files, no shell or user-provided paths.
local setup = require("transformer.shared.easymesh_setup")
local mapping = {
  objectType = {
    name = "rpc.system.easymesh.", access = "readOnly", minEntries = 1, maxEntries = 1,
    parameters = {
      initializable = { access = "readOnly", type = "boolean" },
      initialize = { access = "readWrite", type = "boolean" },
    },
  },
  get = {
    initializable = function() return setup.can_initialize() and "1" or "0" end,
    initialize = "0",
  },
  set = {
    initialize = function(_, _, value)
      if value ~= "1" then return nil, "Initialization requires explicit opt-in." end
      return setup.initialize()
    end,
  },
}
register(mapping)
